Step.SQLStatement:
UPDATE AD_Client SET CostingConfiguration = 'Q' WHERE IsCostImmediate IS NULL OR IsCostImmediate = 'N';
UPDATE AD_Client SET CostingConfiguration = 'I' WHERE IsCostImmediate IS NULL OR IsCostImmediate = 'I';

UPDATE AD_Client SET AccountingConfiguration = 'Q'
WHERE EXISTS (SELECT 1 FROM AD_SysConfig WHERE Name='CLIENT_ACCOUNTING' AND Value='Q' AND AD_Client_ID = 0);
UPDATE AD_Client SET AccountingConfiguration = 'D'
WHERE EXISTS (SELECT 1 FROM AD_SysConfig WHERE Name='CLIENT_ACCOUNTING' AND Value='Q' AND AD_Client_ID = 0);
UPDATE AD_Client SET AccountingConfiguration = 'I'
WHERE EXISTS (SELECT 1 FROM AD_SysConfig WHERE Name='CLIENT_ACCOUNTING' AND Value='Q' AND AD_Client_ID = 0);
UPDATE AD_Client c SET AccountingConfiguration = 'Q'
WHERE EXISTS (SELECT 1 FROM AD_SysConfig sc WHERE Name='CLIENT_ACCOUNTING' AND Value='Q' AND sc.AD_Client_ID = c.AD_Client_ID);
UPDATE AD_Client c SET AccountingConfiguration = 'D'
WHERE EXISTS (SELECT 1 FROM AD_SysConfig sc WHERE Name='CLIENT_ACCOUNTING' AND Value='Q' AND sc.AD_Client_ID = c.AD_Client_ID);
UPDATE AD_Client c SET AccountingConfiguration = 'I'
WHERE EXISTS (SELECT 1 FROM AD_SysConfig sc WHERE Name='CLIENT_ACCOUNTING' AND Value='Q' AND sc.AD_Client_ID = c.AD_Client_ID);
